with open('/app/dataset/genealogy_trees.txt', 'rb') as f:
    data = f.read().decode('utf-8', errors='replace')
    lines = data.split('\n')

# Simple approach: find all names in the tree file
# Names appear as | Name | or │ Name │ patterns
# I'll find all such patterns and their positions

import re

# Find all |...| patterns with proper names
name_positions = []  # (line, col, name)
for i, line in enumerate(lines):
    # Try both | and │
    for ch in ['│', '|']:
        start = 0
        while True:
            idx = line.find(ch, start)
            if idx == -1:
                break
            end = line.find(ch, idx + 1)
            if end == -1:
                end = line.find('│' if ch == '|' else '|', idx + 1)
            if end != -1 and end - idx < 40:
                content = line[idx+1:end].strip()
                if content and len(content) > 1 and any(c.isalpha() for c in content) and not content.startswith(('-', '~', '+', '|', '│')):
                    name_positions.append((i, idx, content))
                    start = end + 1
            else:
                start = idx + 1

# Filter to unique names only
seen_names = set()
for line, col, name in name_positions:
    if name not in seen_names and len(name) > 1:
        seen_names.add(name)
        print(f"Line {line+1}, col {col}: '{name}'")
